import openpyxl


class ExcelProcessor:
    def __init__(self):
        pass

    def read_excel(self, file_name):
        data = []
        try:
            workbook = openpyxl.load_workbook(file_name)
            sheet = workbook.active
            for row in sheet.iter_rows(values_only=True):
                data.append(row)
            workbook.close()
            return data
        except:
            return None

    def write_excel(self, data, file_name):
        try:
            workbook = openpyxl.Workbook()
            sheet = workbook.active
            for row in data:
                sheet.append(row)
            workbook.save(file_name)
            workbook.close()
            return 1
        except:
            return 0

    def is_valid_data_and_column(self, data, N):
        return data is not None and N < len(data[0])

    def transform_value(self, value):
        if str(value).isdigit():
            return value
        else:
            return str(value).upper()

    def process_row(self, row, N):
        new_row = list(row)
        new_row.append(self.transform_value(row[N]))
        return new_row

    def build_output_file_name(self, input_file_name):
        base_name = input_file_name.split('.')[0]
        return base_name + '_process.xlsx'

    def process_excel_data(self, N, save_file_name):
        data = self.read_excel(save_file_name)
        if not self.is_valid_data_and_column(data, N):
            return 0
        new_data = []
        for row in data:
            processed_row = self.process_row(row, N)
            new_data.append(processed_row)
        output_file_name = self.build_output_file_name(save_file_name)
        success = self.write_excel(new_data, output_file_name)
        return success, output_file_name
